 const enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const push=data=>{const bytes=typeof data==='string'?enc.encode(data):data;parts.push(bytes);length+=bytes.length};const object=(id,body)=>{offsets[id]=length;push(`${id} 0 obj\n`);if(Array.isArray(body))body.forEach(push);else push(body);push('\nendobj\n')};
