const logoPngButton=document.createElement('button');logoPngButton.id='downloadBrandLogo';logoPngButton.textContent='HIKAYA · PNG';document.querySelector('footer').append(logoPngButton);logoPngButton.onclick=async()=>{await document.fonts.load('700 264px "Hikaya Arabic"');const canvas=document.createElement('canvas');canvas.width=1560;canvas.height=510;const ctx=canvas.getContext('2d'),mark=await bookImage('assets/hikaya-symbol.svg');ctx.drawImage(mark,1056,36,450,450);ctx.direction='rtl';ctx.textAlign='right';ctx.fillStyle='#215b4c';ctx.font='700 264px "Hikaya Arabic",sans-serif';ctx.fillText('حكاية',966,315,900);ctx.direction='ltr';ctx.fillStyle='#8d7956';ctx.font='500 64px Arial,sans-serif';const letters=[...'HIKAYA'],spacing=20,total=letters.reduce((v,c)=>v+ctx.measureText(c).width,0)+spacing*(letters.length-1);let x=966-total;ctx.textAlign='left';letters.forEach(c=>{ctx.fillText(c,x,435);x+=ctx.measureText(c).width+spacing});download(await canvasBlob(canvas),'hikaya-logo.png')};
